    "title": "IRCC & Canadian Administrative Law: Difference between statute versus policy and ministerial instructions",
    "url": "https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/operational-bulletins-manuals.html",
    "quote": "Under Canadian administrative law, binding statutes like IRPA prevail over operational instructions and departmental policy.",
    "summary": "Under Canadian constitutional and administrative law (*Baker v. Canada*, [1999] 2 S.C.R. 817), there is a strict legal distinction between binding statute and administrative policy. The Immigration and Refugee Protection Act (IRPA, S.C. 2001, c. 27) and its regulations (IRPR) establish statutory requirements enacted by Parliament that bind visa officers and immigration tribunals. Conversely, IRCC Program Delivery Instructions (PDIs), operational bulletins, and ministerial instructions are non-binding administrative guidance; visa officers cannot treat internal policy guidelines as inflexible statutory prerequisites or fetter their discretionary statutory authority.",
    "risk": "high",
    "language": "en",
    "status": "approved",
    "checkedAt": "2026-11-01",
