    "quote": "Under the Charter and federal administrative law, retroactive rule changes are subject to judicial review for procedural fairness.",
    "summary": "Under Section 7 of the Canadian Charter of Rights and Freedoms and Supreme Court administrative fairness standards, prospective applicants and work permit holders in British Columbia (including Surrey) affected by sudden regulatory amendments or retroactive rule changes have rights to procedural fairness. Parliament may enact transitional provisions under IRPA s. 87.3, but administrative changes applied retroactively without clear statutory authority can be challenged before the Federal Court of Canada through an application for leave and judicial review under Section 18.1 of the Federal Courts Act.",
