    "url": "https://www.commerce.wa.gov.au/consumer-protection/rent-increases",
    "quote": "Under the Residential Tenancies Act 1987, landlords can only issue a rent increase once every 12 months with 60 days written notice.",
    "summary": "Under Section 30 of the Western Australia Residential Tenancies Act 1987 and the Residential Tenancies Amendment Act 2024, landlords in Western Australia (including Perth) are legally restricted to issuing a rent increase only once every 12 months (previously 6 months). Landlords must provide tenants with at least 60 days formal written notice using statutory Form 10 (Notice to Tenant of Rent Increase) specifying the exact new rent amount and the date it takes effect. For fixed-term leases, rent increases during the term are strictly prohibited unless the written tenancy agreement specifically provides for the amount or method of calculation.",
