    "summary": "Regional transfers and intercity transit connections across the United Arab Emirates are operated collaboratively by Roads and Transport Authority (RTA) in Dubai and Integrated Transport Centre (ITC) in Abu Dhabi. Scheduled intercity express coaches (such as routes E100 from Al Ghubaiba and E101 from Ibn Battuta to Abu Dhabi Central Bus Station) provide seamless regional connections between Dubai, Abu Dhabi, Sharjah, and Ajman. Passengers execute regional transfers by using contactless Nol cards on Dubai regional lines and switching to Hafilat smart cards upon arriving in Abu Dhabi local bus networks. Buses feature air conditioning, free onboard Wi-Fi, luggage compartments, and full wheelchair accessibility."
