    "summary": "School registration in the United Arab Emirates is governed by federal education directives and supervised by the Knowledge and Human Development Authority (KHDA) in Dubai and the Abu Dhabi Department of Education and Knowledge (ADEK). To register a child in a private or public school, parents must submit the student and sponsor valid Emirates IDs, passports with residency visas, attested birth certificates, immunization records, and an official Transfer Certificate (TC) from the previous school (attested by the Ministry of Foreign Affairs MOFA if arriving from abroad). Admissions portals open in January/February for the September academic cycle and October for the April cycle."
