    "summary": "Resume screening and applicant evaluation in the United Arab Emirates are governed by fair recruitment principles under Federal Decree-Law No. 33 of 2021. Employers and corporate recruitment agencies frequently utilize digital Applicant Tracking Systems (ATS) to screen resumes against job descriptions, requiring clean formatting, relevant keyword alignment, and verified educational credentials. MOHRE regulations prohibit discrimination in candidate screening based on race, colour, sex, religion, national origin, or social origin. Applicants should ensure contact details include a UAE phone number, residency visa status, and professional LinkedIn profiles."
