    "url": "https://www.workandincome.govt.nz/work",
    "quote": "Job search without local experience in New Zealand is supported through Connected and Work and Income employment programmes for newcomers and job seekers.",
    "summary": "Job search without local experience in New Zealand is facilitated by the Ministry of Social Development (MSD) through the Connected employment service and Work and Income job search centres. Newcomers seeking to enter the Kiwi workforce can access career matching, CV tailoring seminars, and wage subsidies (Flexi-Wage) designed to incentivize employers to hire job seekers who require on-the-job training. In addition, organizations such as New Zealand Chamber of Commerce run newcomer mentorship schemes connecting foreign-trained professionals with local industry mentors."
