    "summary": "Credential recognition and foreign degree evaluation in New Zealand are administered by the New Zealand Qualifications Authority (NZQA) under the Education and Training Act 2020. Individuals with overseas degrees, diplomas, or trade certificates apply for an International Qualifications Assessment (IQA) to determine the equivalent level on the New Zealand Qualifications Framework (NZQF Levels 1 to 10). The resulting evaluation report serves as authoritative evidence for Immigration New Zealand skilled migrant visa applications and registration with professional regulatory bodies (such as the Teaching Council or Engineering New Zealand)."
