    "summary": "Apprenticeship pathway schemes in New Zealand are structured under the New Zealand Apprenticeships framework regulated by the Tertiary Education Commission (TEC) and delivered through Te Pūkenga (New Zealand Institute of Skills and Technology) and Industry Training Organisations (ITOs). Apprentices enter into a tripartite training agreement with their employer and training provider, earning statutory training wages while completing work-based unit standards and block courses toward a National Certificate or New Zealand Certificate at NZQF Level 4 in trades such as carpentry, plumbing, automotive engineering, and electrical trades."
