    "summary": "Recruitment fees charged to job seekers are illegal in New Zealand under Section 12A of the Wages Protection Act 1983 and the Employment Relations Act 2000. Employers and employment agents are strictly forbidden from demanding, receiving, or deducting any premium, fee, or financial payment from an employee or prospective worker in exchange for employment, job offers, or Accredited Employer Work Visa (AEWV) support. Charging recruitment fees constitutes unlawful migrant exploitation, punishable by severe financial penalties, employer accreditation revocation, and criminal prosecution by the MBIE Labour Inspectorate."
