    "quote": "UK family reunification under Immigration Rules Appendix FM requires the sponsor to meet the statutory Minimum Income Requirement, adequate accommodation, and genuine partnership proof.",
    "summary": "Family reunification in the United Kingdom is governed by Appendix FM of the Immigration Rules administered by the Home Office. British citizens, persons settled in the UK (with ILR or settled status), and eligible refugee status holders can sponsor spouses, civil partners, unmarried partners (cohabiting for at least 2 years), and dependent children. Sponsors must satisfy the Minimum Income Requirement (MIR) under Appendix FM-SE through salaried employment, self-employment, pensions, or verified cash savings held for 6 months. In addition, the applicant must demonstrate English language proficiency at CEFR Level A1 (or higher for extensions), provide evidence of adequate accommodation that is not overcrowded, and prove a genuine and subsisting relationship."
