    "jurisdiction": "United Kingdom",
    "url": "https://www.actionfraud.police.uk/a-z-of-fraud/rental-fraud",
    "quote": "Rental fraud in the UK is prevented by inspecting properties in person, verifying landlord ownership via Land Registry, and using statutory Tenancy Deposit Schemes.",
    "summary": "Rental fraud and tenancy scams in the United Kingdom are investigated by Action Fraud and local Trading Standards authorities. Common rental fraud involves bogus landlords advertising properties they do not own, requesting deposits via wire transfer prior to viewings, or taking holding deposits without tenancy agreements. To prevent rental fraud, prospective tenants should conduct in-person viewings, verify title ownership via the official HM Land Registry (£3 search), ensure holding deposits comply with the Tenant Fees Act 2019 (maximum 1 week rent), and confirm security deposits are protected within 30 days in one of the three government-approved custodial schemes (DPS, TDS, or MyDeposits)."
