    "quote": "Resume screening in the UK is protected under the Equality Act 2010, prohibiting discrimination on age, race, sex, disability, or religion, encouraging name-blind recruitment.",
    "summary": "Resume screening and recruitment shortlisting in the United Kingdom are subject to the Equality Act 2010 enforced by the Equality and Human Rights Commission (EHRC). Employers are legally prohibited from discriminating against applicants based on any protected characteristic: age, disability, gender reassignment, race, religion, sex, or sexual orientation. Many public and private employers implement \"blind recruitment\" (removing names, age, and schools from CVs) to prevent unconscious bias. Pre-employment health questions are strictly prohibited under Section 60 of the Equality Act except for establishing reasonable adjustments needed for interviews."
