    "topic": "employment",
    "jurisdiction": "United Kingdom",
    "url": "https://www.gov.uk/employment-status",
    "quote": "Under UK employment law, courts apply mutuality of obligation and control tests to resolve worker misclassification and sham self-employment under ERA 1996.",
    "summary": "Worker misclassification in the United Kingdom is adjudicated under the Employment Rights Act 1996 (ERA) and National Minimum Wage Act 1998. UK law recognises three distinct employment statuses: employee, worker, and self-employed independent contractor. To prevent sham self-employment, Employment Tribunals apply established common law tests: control (degree of supervision), personal service (requirement to do work personally versus right of substitution), and mutuality of obligation. Misclassified individuals deemed \"workers\" or \"employees\" are legally entitled to statutory holiday pay under the Working Time Regulations 1998, National Minimum Wage back-pay, and pension contributions."
