    "quote": "Credit building in Australia is regulated under Comprehensive Credit Reporting (CCR) under the Privacy Act 1988, where maintaining 24 months of on-time repayments establishes a positive score.",
    "summary": "Credit building in Australia operates under the Comprehensive Credit Reporting (CCR) regime established by amendments to the Privacy Act 1988 (Part IIIA) and the National Consumer Credit Protection Act 2009. Credit reporting bodies (Equifax, Experian, and illion) record both negative information (defaults, bankruptcies) and positive information (account open dates, credit limits, and 24 months of on-time monthly repayment history). Newcomers and migrants build Australian credit by opening a bank transaction account, paying utility bills and postpaid mobile phone contracts punctually, and maintaining credit facilities (such as an overdraft or credit card) with consistent on-time payments. Credit scores in Australia range from 0 to 1,000 or 1,200 depending on the bureau. Consumers have the statutory right under the Privacy Act to obtain their credit report for free every three months."
