    "url": "https://www.servicesaustralia.gov.au/jobseeker-payment",
    "quote": "Australia employment insurance equivalent is the means-tested JobSeeker Payment administered by Services Australia under the Social Security Act 1991, subject to income/asset tests and mutual obligations.",
    "summary": "Employment insurance in Australia is provided through the statutory social security safety net as JobSeeker Payment under the Social Security Act 1991, administered by Services Australia (Centrelink). Australia does not operate a contributory employer-levied unemployment insurance scheme; instead, income support is non-contributory and means-tested. To qualify, an applicant must be aged 22 up to Age Pension age, unemployed or looking for work, satisfy income and assets tests, and meet the residence rules (being an Australian citizen, permanent visa holder, or eligible protected Special Category Visa holder). Permanent migrants are generally subject to the Newly Arrived Resident Waiting Period (NARWP) of up to 4 years before accessing JobSeeker, unless exempted under substantial change of circumstances or refugee criteria. Recipients must satisfy mutual obligation requirements (job searches, training, or Work for the Dole) through the Workforce Australia portal."
