    "url": "https://www.fairwork.gov.au/employment-conditions/general-protections",
    "quote": "Under Australia Fair Work Act 2009 Section 351, employers cannot discriminate against candidates during resume screening based on race, gender, age, or disability.",
    "summary": "Resume screening and applicant shortlisting in Australia are protected by general protections provisions under Section 351 of the Fair Work Act 2009 and Commonwealth anti-discrimination legislation. Prospective employers are legally prohibited from taking adverse action—including refusing to interview or hire—against an applicant on discriminatory grounds including race, sex, sexual orientation, age, physical or mental disability, marital status, or national extraction. Australian resumes should focus on relevant core competencies, Australian work authorization status, and professional achievements."
