    "quote": "US adult language classes are funded under WIOA Title II, offering free or low-cost English as a Second Language (ESL) instruction through community colleges and adult education school districts.",
    "summary": "Language classes in the United States are federally authorized and funded under the Workforce Innovation and Opportunity Act (WIOA Title II - Adult Education and Family Literacy Act, 29 U.S.C. § 3271 et seq.) administered by the U.S. Department of Education Office of Career, Technical, and Adult Education (OCTAE). Under WIOA, state adult education agencies and local community colleges, public school adult education divisions, and community organizations provide free or low-cost English as a Second Language (ESL / ELL) classes and Integrated English Literacy and Civics Education (IELCE). Adult immigrants, refugees, and newcomers are eligible to enroll regardless of visa type to gain practical English communication, workplace vocabulary, and preparation for citizenship interviews. Placement tests determine class level from beginner literacy to advanced academic preparation."
