    "summary": "Apprenticeship pathway schemes in the United States operate under the National Apprenticeship Act (29 U.S.C. § 50) administered by the U.S. Department of Labor (DOL) Office of Apprenticeship and State Apprenticeship Agencies. Registered Apprenticeships combine paid on-the-job training under experienced mentors with at least 144 hours of related classroom instruction per year. Apprentices earn progressive wage increases as their skills advance, completing industry-recognized credentials in fields ranging from construction and manufacturing to cybersecurity and healthcare."
