    "topic": "community",
    "jurisdiction": "Germany",
    "url": "https://service.berlin.de/dienstleistung/324280",
    "quote": "Germany permanent residence (Niederlassungserlaubnis) does not expire, but the physical eAT residence card must be renewed at the Ausländerbehörde upon passport expiry with a biometric photo.",
    "summary": "PR card renewal in Germany concerns the renewal of the electronic residence title card (elektronischer Aufenthaltstitel - eAT) for holders of a permanent settlement permit (Niederlassungserlaubnis) or EU Long-Term Residence (Erlaubnis zum Daueraufenthalt-EU). Under § 78 of the Residence Act (AufenthG), the substantive permanent right of residence does not expire; however, the plastic eAT card has a technical validity tied to the expiry date of the cardholder passport (maximum 10 years). To renew the physical eAT card, the permanent resident books an appointment at their local Immigration Office (Ausländerbehörde / Landesamt für Einwanderung LEA), presents their renewed passport, a current biometric passport photograph, and their existing eAT card, and pays the administrative card issuance fee of approximately €67."
