    "quote": "Credit building across EU member states is regulated by the Consumer Credit Directive, establishing creditworthiness assessments and credit bureau transparency.",
    "summary": "Credit building in the European Union operates under national credit registers regulated by the EU Consumer Credit Directive (Directive 2008/48/EC and Directive (EU) 2023/2225) and the General Data Protection Regulation (GDPR). Unlike single national score models, EU credit building relies on creditworthiness checks conducted by banks using national credit bureaus (such as SCHUFA in Germany, BKR in the Netherlands, and ASNEF in Spain). Newcomers establish creditworthiness across the EU by maintaining stable local bank accounts, receiving direct salary deposits, and ensuring timely payments on utility and postpaid telecommunication contracts."
