    "summary": "Student transit fares and transport concessions across the European Union are provided by municipal and regional transport authorities under national youth mobility policies. University students and vocational trainees enrolled in accredited EU higher education institutions qualify for subsidized local transit passes (such as Semestertickets in Germany, student Navigo passes in France, or student OV-chipkaart in the Netherlands). Furthermore, holders of the European Youth Card (EYCA) and International Student Identity Card (ISIC) access concessionary fares on long-distance trains and buses across participating member states."
