    "url": "https://europa.eu/youreurope/citizens/family/children/family-benefits/index_en.htm",
    "quote": "Under EU Regulation 883/2004, child benefit and family allowances are coordinated across member states so families receive the highest applicable statutory allowance.",
    "summary": "Child benefit and family allowances across the European Union are coordinated under EU Regulation (EC) No 883/2004 on the coordination of social security systems. When family members live, work, or reside in different EU member states, priority rules determine which country pays the primary family benefits (typically the country of employment). If the family benefit in the country of employment is lower than what the country of residence would pay, the resident country pays a differential supplement (top-up payment), ensuring the family receives the highest level of child benefit to which they are entitled under national laws."
