    "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32019L1152",
    "quote": "EU labour standards protect employees against wrongful dismissal through the Transparent and Predictable Working Conditions Directive and mandatory statutory notice periods.",
    "summary": "Wrongful dismissal protections across the European Union are established through the EU Charter of Fundamental Rights (Article 30) and Directive (EU) 2019/1152 on transparent and predictable working conditions. National employment legislation across member states mandates that dismissals must be justified by valid business reasons or employee conduct, with statutory minimum notice periods and written termination notices. Dismissals motivated by pregnancy, trade union activity, discrimination, or exercising statutory rights are void as wrongful dismissal, entitling workers to reinstatement or severance compensation awarded by labour tribunals."
