    "quote": "Under the EU Reception Conditions Directive, asylum seekers and refugees are guaranteed necessary healthcare including emergency care and essential treatment of illness.",
    "summary": "Refugee health coverage across the European Union is governed by the Reception Conditions Directive (Directive 2013/33/EU) and national asylum legislation. Under Article 19 of the Directive, member states are legally obligated to provide asylum seekers and beneficiaries of temporary or subsidiary protection with necessary healthcare, including emergency medical treatment, essential therapy for serious illnesses, and comprehensive maternity care. Once recognized as refugees, individuals are integrated directly into the national statutory health insurance system on equal terms with domestic citizens."
