    "summary": "Mental health support across the European Union is coordinated under the Comprehensive Approach to Mental Health and Directive 2011/24/EU on patients rights in cross-border healthcare. European residents can access psychological consultations, psychiatric therapies, and crisis counseling through national statutory health insurance systems. In emergency mental health crises, acute medical stabilization is available at public hospital emergency departments and specialized psychiatric emergency clinics nationwide without upfront payment barriers for insured persons."
