    "quote": "Under EU Regulation 883/2004, employment insurance periods are aggregated across member states, allowing job seekers to export unemployment benefits for up to 6 months.",
    "summary": "Employment insurance and unemployment benefits across the European Union are governed by EU Regulation (EC) No 883/2004. Under the principle of aggregation of insurance periods, periods of insurance, employment, or self-employment completed in one EU member state count toward fulfilling eligibility conditions for unemployment benefits in another member state using document U1. In addition, an unemployed person who qualifies for benefits in one member state can export their unemployment benefit (document U2) for 3 to 6 months while seeking employment in another EU country."
