    "quote": "Under EU motor insurance rules, motor insurers must take into account driving history statements and no-claims bonuses from other EU member states on equal terms.",
    "summary": "Driving history recognition and transferring driving records between European Union member states are governed by Directive 2009/103/EC on motor vehicle insurance as amended by Directive (EU) 2021/2118. When moving between EU member states, drivers are legally entitled to request an official Claims History Statement (no-claims certificate) from their previous motor insurer covering the preceding 5 years. Auto insurers in the destination member state are required by EU law not to discriminate against drivers based on nationality or previous EU residence, applying their claims history to calculate no-claims discounts on car insurance."
