    "quote": "Council Directive 2003/86/EC establishes common rules governing the right to family reunification for third-country nationals.",
    "summary": "Under Council Directive 2003/86/EC, third-country nationals holding a valid residence permit in an EU Member State for a period of one year or more with reasonable prospects of obtaining permanent residence have the right to sponsor their spouse and minor children for family reunification. Sponsors must demonstrate adequate housing, sickness insurance, and stable and regular resources sufficient to maintain themselves without recourse to social assistance.",
